class SmartLamp {
  constructor(initialBrightness) {
    // TODO: Make 'isOn' private and initialize to false
    this.isOn = false;
    // TODO: Make 'brightnessLevel' private and set using the 'setBrightness' method
    this.brightnessLevel = initialBrightness;
  }

  turnOn() {
    // TODO: Use the private 'isOn' field
    this.isOn = true;
    return "Lamp is ON.";
  }

  turnOff() {
    // TODO: Use the private 'isOn' field
    this.isOn = false;
    return "Lamp is OFF.";
  }

  setBrightness(level) {
    // TODO: Make 'brightnessLevel' private and add validation (0-100)
    // Avoid unnecessary nesting by using guard clauses.
    if (level < 0) {
      return "Brightness cannot be negative.";
    }
    if (level > 100) {
      return "Brightness cannot exceed 100.";
    }
    this.brightnessLevel = level;
    return `Brightness set to ${this.brightnessLevel}.`;
  }

  getStatus() {
    // TODO: Return an object with the private 'isOn' and 'brightnessLevel' values
    return { isOn: this.isOn, brightness: this.brightnessLevel };
  }
}

