class SmartLamp {
  #isOn;
  #brightnessLevel;

  constructor(initialBrightness) {
    this.#isOn = false;
    this.setBrightness(initialBrightness);
  }

  turnOn() {
    this.#isOn = true;
    return "Lamp is ON.";
  }

  turnOff() {
    this.#isOn = false;
    return "Lamp is OFF.";
  }

  setBrightness(level) {
    if (level < 0 || level > 100) {
      return "Invalid brightness level. Must be between 0 and 100.";
    }
    this.#brightnessLevel = level;
    return `Brightness set to ${this.#brightnessLevel}.`;
  }

  getStatus() {
    return { isOn: this.#isOn, brightness: this.#brightnessLevel };
  }
}

